import{_ as t,o,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Community Initiatives and Improving Ceph through User Feedback | Ceph Days NYC 2024","description":"","frontmatter":{"title":"Community Initiatives and Improving Ceph through User Feedback | Ceph Days NYC 2024","date":"2024-05-23T00:00:00.000Z","updated":"2024-05-24T00:00:00.000Z","tags":["Ceph 用户反馈","分布式存储","性能优化","社区协作","用户开发会议"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024.md","filePath":"posts/2024/Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Community_Initiatives_and_Improving_Ceph_through_User_Feedback_Ceph_Days_NYC_2024.md"};function l(a,i,s,p,g,_){return o(),e("div",null,[...i[0]||(i[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> SEF用户委员会的启动</p><p><strong>会议时间：</strong> [具体日期]</p><p><strong>会议地点：</strong> 线上会议</p><p><strong>主持人：</strong> Laura Flores</p><p><strong>参会人员：</strong> SEF项目团队成员、社区成员</p><p><strong>会议目标：</strong> 介绍SEF用户委员会的成立目的、工作流程、初步调查反馈及后续行动计划。</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>目标介绍：</strong></p><ul><li>SEF用户委员会旨在收集用户反馈，改进SEF项目，提高性能和编排部署。</li><li>历史活动包括SEF Days、SEF Lons、虚拟论坛和用户开发者会议。</li><li>新倡议希望集中用户反馈，转化为具体行动项。</li></ul></li><li><p><strong>工作流程：</strong></p><ul><li>用户委员会将聚焦于性能和编排部署两大支柱。</li><li>设立冠军（Champions）角色，负责引导讨论和组织相关议题。</li><li>通过调查问卷收集用户反馈，冠军将协助设计问卷问题。</li><li>调查结果将通过数据可视化处理，并与遥测数据关联分析。</li></ul></li><li><p><strong>初步调查反馈：</strong></p><ul><li>调查集中在性能和编排部署方面，收集了27份反馈。</li><li>性能方面，用户普遍满意，但也提出了如mclock控制、长时间回填性能下降等问题。</li><li>编排部署方面，用户对自动化和易用性满意，但也指出了日志和错误处理、文档不足等问题。</li></ul></li><li><p><strong>后续行动计划：</strong></p><ul><li>根据初步反馈调整问卷，扩大调查范围，增加社交媒体和口口相传的宣传。</li><li>计划在下次用户开发者会议上讨论具体行动项。</li><li>鼓励社区成员成为冠军，负责其他支柱如质量、可扩展性等。</li></ul></li><li><p><strong>下次会议安排：</strong></p><ul><li>下次用户开发者会议定于每月第三个周四的14:00 UTC，下次会议日期为5月16日。</li><li>感兴趣成为冠军的成员可通过电子邮件联系Laura或N。</li></ul></li></ol><p><strong>行动项：</strong></p><ul><li>调整并发布新的调查问卷。</li><li>在社交媒体和社区中扩大宣传，吸引更多用户参与。</li><li>在下次用户开发者会议上讨论并确定具体行动项。</li><li>招募更多冠军，负责其他SEF支柱的改进工作。</li></ul><p><strong>会议结束语：</strong> 感谢所有参与者的贡献，期待社区的积极参与和反馈，共同推动SEF项目的改进和发展。</p><p><strong>备注：</strong></p><ul><li>会议记录和相关资料将通过邮件列表和社区平台共享。</li><li>如有关于会议的任何疑问或建议，请及时联系会议组织者。</li></ul><p><strong>关键字保留：</strong></p><ul><li>Ceph, distributed storage, CRUSH algorithm, high availability, scalability, object storage, block storage, file system storage, consistency, decentralization, performance, bluestore, bluefs, rocksdb, OSD, MON, MDS, PG, RADOS, librados, libcephfs, cephfs, rbd, radosgw, RGW, RESTful API, authentication, authorization, encryption, erasure coding, replication, snapshots, clones, thin provisioning, iSCSI, Fibre Channel, NFS, CIFS, POSIX, monitoring, dashboard, management, orchestration, automation, integration, containerization, Kubernetes, Docker, virtualization, cloud computing, AWS, Azure, Google Cloud, hybrid cloud, multi-cloud, storage cluster, node, disk, SSD, HDD, JBOD, SAN, NAS, network, topology, failure domain, recovery, resilience, load balancing, caching, compression, deduplication, tiering, performance tuning, benchmarking, testing, validation</li></ul>',16)])])}const d=t(r,[["render",l]]);export{c as __pageData,d as default};
